import type { WritingSample } from '@/data/writing-samples';

type ParagraphSeed = { en: string; vi: string; focusVi: string };
type OpinionSeed = {
  id: string;
  topicSlug: string;
  topicEn: string;
  topicVi: string;
  title: string;
  promptText: string;
  paragraphs: [ParagraphSeed, ParagraphSeed, ParagraphSeed, ParagraphSeed];
  vocabulary: WritingSample['vocabulary'];
};

const SECTIONS = ['introduction', 'body1', 'body2', 'conclusion'] as const;

function makeOpinion(seed: OpinionSeed): WritingSample {
  return {
    ...seed,
    task: 'ielts_task2',
    essayKind: 'opinion',
    promptId: `w-${seed.id}`,
    // Nhãn mục tiêu để học; không phải điểm số đã được thẩm định.
    band: 8.0,
    paragraphs: seed.paragraphs.map((part, index) => ({
      id: `${seed.id}-p${index + 1}`,
      section: SECTIONS[index]!,
      ...part,
    })),
  };
}

const SEEDS: OpinionSeed[] = [
  {
    id: 'sample-t2-extra-opinion-education', topicSlug: 'education', topicEn: 'Education', topicVi: 'Giáo dục',
    title: 'Financial literacy at school',
    promptText: 'Schools should teach all students how to manage personal finances before they graduate. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Many young adults leave school able to solve abstract problems but unsure how to read a payslip, compare a loan or plan a monthly budget. I strongly agree that financial literacy should be part of secondary education. These skills are relevant to almost every student, and teaching them early can prevent avoidable mistakes when young people first manage money independently.', vi: 'Nhiều người trẻ rời trường có thể giải bài toán trừu tượng nhưng không biết đọc phiếu lương, so sánh khoản vay hay lập ngân sách tháng. Tôi hoàn toàn đồng ý rằng kiến thức tài chính nên là một phần của giáo dục trung học. Những kỹ năng này liên quan đến hầu hết học sinh, và dạy sớm có thể ngăn các sai lầm đáng tránh khi họ lần đầu tự quản lý tiền.', focusVi: 'Mở bài nêu vấn đề và lập trường đồng ý rõ ràng.' },
      { en: 'A practical course could explain interest, taxes, savings and the difference between essential and discretionary spending. For example, students might compare the total cost of buying a phone on credit with paying upfront, then discuss why a low monthly payment can conceal expensive interest. They could also practise planning for rent, transport and food using a realistic entry-level salary. Such lessons turn mathematics into a tool for daily decisions rather than a subject that feels detached from adult life.', vi: 'Một môn học thực tế có thể giải thích lãi suất, thuế, tiết kiệm và sự khác nhau giữa chi tiêu thiết yếu với chi tiêu tuỳ ý. Chẳng hạn, học sinh có thể so sánh tổng chi phí mua điện thoại trả góp với trả ngay, rồi thảo luận vì sao khoản thanh toán hằng tháng thấp có thể che giấu tiền lãi cao. Các em cũng có thể luyện lập kế hoạch cho tiền thuê nhà, đi lại và thực phẩm dựa trên mức lương khởi điểm thực tế. Bài học như vậy biến toán học thành công cụ cho quyết định thường ngày thay vì môn học xa rời cuộc sống trưởng thành.', focusVi: 'Thân bài 1 cụ thể hoá nội dung môn học và lợi ích ứng dụng.' },
      { en: 'Critics may argue that schools are already crowded with subjects and that parents should teach children about money. Families certainly influence spending habits, but not every household has the knowledge or time to explain borrowing and consumer contracts. A common curriculum would give students a basic level of protection regardless of their background. It should not prescribe one lifestyle; instead, it should help learners recognise risk, ask informed questions and make choices that fit their circumstances.', vi: 'Người phản đối có thể cho rằng chương trình học đã quá tải và cha mẹ nên dạy con về tiền bạc. Gia đình chắc chắn ảnh hưởng đến thói quen chi tiêu, nhưng không phải hộ nào cũng có kiến thức hoặc thời gian giải thích vay mượn và hợp đồng tiêu dùng. Chương trình chung sẽ đem lại mức bảo vệ cơ bản cho học sinh bất kể hoàn cảnh. Môn học không nên áp đặt một lối sống; thay vào đó, cần giúp người học nhận diện rủi ro, đặt câu hỏi có hiểu biết và đưa ra lựa chọn phù hợp với điều kiện của mình.', focusVi: 'Thân bài 2 nhượng bộ về chương trình học rồi phản biện bằng tính công bằng.' },
      { en: 'Financial education cannot remove poverty or guarantee sensible decisions, but it can make young people less vulnerable to costly confusion. Schools should teach it through practical examples and update the material as financial products change. Giving every student this foundation is a modest use of class time with benefits that can continue well beyond graduation.', vi: 'Giáo dục tài chính không thể xoá nghèo hay bảo đảm mọi quyết định đều khôn ngoan, nhưng có thể giúp người trẻ ít bị tổn thương bởi sự thiếu hiểu biết tốn kém. Trường học nên dạy qua ví dụ thực tế và cập nhật nội dung khi sản phẩm tài chính thay đổi. Cung cấp nền tảng này cho mọi học sinh chỉ chiếm một phần thời gian học khiêm tốn nhưng lợi ích có thể kéo dài sau khi tốt nghiệp.', focusVi: 'Kết luận nhắc giới hạn nhưng khẳng định giá trị lâu dài của đề xuất.' },
    ],
    vocabulary: [
      { phrase: 'financial literacy', meaningVi: 'kiến thức và năng lực tài chính', noteVi: 'Cụm bao quát khả năng hiểu và sử dụng thông tin về tiền.' },
      { phrase: 'discretionary spending', meaningVi: 'chi tiêu tuỳ ý', noteVi: 'Khoản chi không thuộc nhu cầu thiết yếu.' },
      { phrase: 'entry-level salary', meaningVi: 'mức lương khởi điểm', noteVi: 'Cụm hữu ích khi đưa ví dụ về người mới đi làm.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-environment', topicSlug: 'environment', topicEn: 'Environment', topicVi: 'Môi trường',
    title: 'Individual action and environmental protection',
    promptText: 'Some people believe that individuals cannot do much to protect the environment and that only governments and businesses can make a difference. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Environmental damage is often caused on a scale that seems far beyond the control of one household. Nevertheless, I disagree that individuals are powerless. Personal choices alone cannot replace regulation, but they can reduce demand for harmful practices and help create the public pressure needed for larger institutions to change.', vi: 'Tổn hại môi trường thường diễn ra ở quy mô có vẻ vượt xa khả năng kiểm soát của một hộ gia đình. Dù vậy, tôi không đồng ý rằng cá nhân hoàn toàn bất lực. Lựa chọn riêng lẻ không thể thay thế quy định, nhưng có thể giảm nhu cầu đối với những hoạt động gây hại và tạo sức ép xã hội cần thiết để các tổ chức lớn thay đổi.', focusVi: 'Mở bài nêu lập trường phản đối tuyệt đối và đặt quan hệ bổ trợ.' },
      { en: 'Households influence the market through what they buy, how long they use it and whether they repair or replace it. Choosing durable goods, reducing food waste and using public transport when practical may appear small, yet repeated across millions of people these habits affect production and emissions. Consumers can also reward firms that disclose their supply chains and avoid companies with demonstrably poor practices. Their influence is limited, but it is more than symbolic when choices are sustained and widely shared.', vi: 'Hộ gia đình ảnh hưởng đến thị trường qua thứ họ mua, thời gian sử dụng và việc sửa chữa hay thay mới. Chọn đồ bền, giảm lãng phí thực phẩm và dùng giao thông công cộng khi thuận tiện có thể trông nhỏ bé, nhưng khi hàng triệu người cùng làm, thói quen này tác động đến sản xuất và phát thải. Người tiêu dùng cũng có thể ủng hộ doanh nghiệp công khai chuỗi cung ứng và tránh các công ty có hoạt động kém rõ ràng. Ảnh hưởng của họ có giới hạn, nhưng không chỉ mang tính biểu tượng nếu lựa chọn được duy trì và chia sẻ rộng rãi.', focusVi: 'Thân bài 1 giải thích tác động của lựa chọn cá nhân thông qua thị trường.' },
      { en: 'More importantly, residents vote, join local organisations and influence what politicians consider urgent. A community that repeatedly requests safe cycle routes or better insulation can make a neglected issue visible and build support for public investment. Governments still need to set binding standards and businesses must redesign polluting processes; citizens cannot inspect every factory themselves. However, policy is easier to introduce and enforce when the public understands why it matters and expects leaders to act.', vi: 'Quan trọng hơn, cư dân đi bầu, tham gia tổ chức địa phương và ảnh hưởng đến điều mà chính trị gia xem là cấp bách. Cộng đồng liên tục yêu cầu làn xe đạp an toàn hoặc cách nhiệt tốt hơn có thể khiến vấn đề bị bỏ quên trở nên rõ ràng và tạo ủng hộ cho đầu tư công. Chính phủ vẫn cần đặt tiêu chuẩn bắt buộc và doanh nghiệp phải thiết kế lại quy trình gây ô nhiễm; công dân không thể tự kiểm tra từng nhà máy. Tuy nhiên, chính sách dễ được thông qua và thực thi hơn khi công chúng hiểu vì sao nó quan trọng và mong lãnh đạo hành động.', focusVi: 'Thân bài 2 mở rộng vai trò cá nhân sang vận động cộng đồng và trách nhiệm thể chế.' },
      { en: 'Individuals cannot solve climate change by shopping carefully, and telling them otherwise would unfairly shift responsibility away from powerful actors. Yet citizens are consumers, voters and neighbours whose combined choices shape both markets and policy. Environmental progress is strongest when personal action reinforces firm regulation rather than being treated as a substitute for it.', vi: 'Cá nhân không thể giải quyết biến đổi khí hậu chỉ bằng cách mua sắm cẩn thận, và nói ngược lại sẽ chuyển trách nhiệm một cách bất công khỏi những chủ thể quyền lực. Tuy nhiên, công dân vừa là người tiêu dùng, cử tri, vừa là hàng xóm; những lựa chọn cộng lại của họ định hình cả thị trường lẫn chính sách. Tiến bộ môi trường mạnh nhất khi hành động cá nhân củng cố quy định nghiêm túc thay vì bị xem là vật thay thế.', focusVi: 'Kết luận phân định giới hạn trách nhiệm cá nhân và chốt giải pháp kết hợp.' },
    ],
    vocabulary: [
      { phrase: 'binding standards', meaningVi: 'tiêu chuẩn có tính bắt buộc', noteVi: 'Cụm dùng khi nói về quy định pháp lý.' },
      { phrase: 'public pressure', meaningVi: 'sức ép từ công chúng', noteVi: 'Kết hợp tự nhiên với build, create hoặc exert.' },
      { phrase: 'shift responsibility away from', meaningVi: 'chuyển trách nhiệm khỏi', noteVi: 'Cấu trúc hữu ích để phân tích trách nhiệm xã hội.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-technology', topicSlug: 'technology', topicEn: 'Technology', topicVi: 'Công nghệ',
    title: 'Smartphones for teenagers',
    promptText: 'Children under the age of sixteen should not be allowed to own a smartphone. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Smartphones give teenagers access to learning and social connection, but they also expose them to distraction and online harm. I disagree with a complete ban on ownership for everyone under sixteen. Families should set age-appropriate limits, while schools and technology companies share responsibility for making the devices safer.', vi: 'Điện thoại thông minh giúp thanh thiếu niên tiếp cận việc học và kết nối xã hội, nhưng cũng khiến các em đối mặt với xao nhãng và nguy cơ trên mạng. Tôi không đồng ý với lệnh cấm hoàn toàn quyền sở hữu đối với mọi người dưới mười sáu tuổi. Gia đình nên đặt giới hạn phù hợp độ tuổi, còn trường học và công ty công nghệ cùng chịu trách nhiệm làm thiết bị an toàn hơn.', focusVi: 'Mở bài nêu lập trường phản đối cấm tuyệt đối và hướng đến quản lý phù hợp.' },
      { en: 'For many teenagers, a phone is a practical safety tool. They can contact a parent after a late activity, check a bus disruption or ask for help if plans change. It can also provide access to dictionaries, educational material and group work, especially for pupils who share a computer at home. Preventing all young people from owning a device would ignore these differences and could isolate those who rely on it for ordinary communication.', vi: 'Với nhiều thanh thiếu niên, điện thoại là công cụ an toàn thiết thực. Các em có thể liên hệ cha mẹ sau hoạt động muộn, kiểm tra sự cố xe buýt hoặc nhờ giúp đỡ khi kế hoạch thay đổi. Điện thoại còn mở lối đến từ điển, tài liệu học và làm việc nhóm, nhất là học sinh phải dùng chung máy tính ở nhà. Ngăn mọi người trẻ sở hữu thiết bị sẽ bỏ qua những khác biệt này và có thể cô lập những em cần nó cho giao tiếp thường ngày.', focusVi: 'Thân bài 1 trình bày lợi ích thực tế và nhóm cần thiết bị.' },
      { en: 'The risks are real, particularly when social applications are designed to keep users scrolling. Late-night notifications can reduce sleep, and an inexperienced user may share personal information without understanding how widely it can spread. These dangers call for safeguards rather than a single age rule: parents can agree on screen-free periods, schools can teach privacy and critical judgement, and platforms can provide private-by-default accounts with effective reporting tools. Restrictions should become more independent as a teenager demonstrates maturity.', vi: 'Rủi ro là có thật, đặc biệt khi ứng dụng xã hội được thiết kế để giữ người dùng lướt mãi. Thông báo ban đêm có thể làm giảm giấc ngủ, còn người thiếu kinh nghiệm có thể chia sẻ thông tin cá nhân mà không hiểu nó lan rộng đến đâu. Những nguy cơ này đòi hỏi biện pháp bảo vệ thay vì một quy tắc tuổi tác duy nhất: cha mẹ có thể thống nhất giờ không dùng màn hình, trường học dạy quyền riêng tư và phán đoán phản biện, còn nền tảng cung cấp tài khoản mặc định riêng tư cùng công cụ báo cáo hiệu quả. Hạn chế nên nới dần khi thanh thiếu niên thể hiện sự trưởng thành.', focusVi: 'Thân bài 2 thừa nhận rủi ro và đưa ra giải pháp theo từng chủ thể.' },
      { en: 'Ownership by itself does not determine whether a teenager uses a phone well or badly. A blanket ban may remove useful contact without teaching the judgement needed later, whereas guided access builds habits gradually. The more balanced policy is to combine parental boundaries, digital education and stronger platform protections, with freedom increasing as young people become more responsible.', vi: 'Việc sở hữu tự nó không quyết định thanh thiếu niên sử dụng điện thoại tốt hay xấu. Lệnh cấm chung có thể lấy đi phương tiện liên lạc hữu ích mà không dạy khả năng phán đoán cần thiết về sau, trong khi tiếp cận có hướng dẫn giúp hình thành thói quen dần dần. Chính sách cân bằng hơn là kết hợp ranh giới do cha mẹ đặt ra, giáo dục số và bảo vệ mạnh hơn từ nền tảng, đồng thời tăng quyền tự do khi người trẻ có trách nhiệm hơn.', focusVi: 'Kết luận nhấn mạnh cách tiếp cận tăng quyền tự chủ theo độ trưởng thành.' },
    ],
    vocabulary: [
      { phrase: 'age-appropriate limits', meaningVi: 'giới hạn phù hợp với độ tuổi', noteVi: 'Cụm dùng khi đề xuất quy tắc linh hoạt cho trẻ.' },
      { phrase: 'private-by-default', meaningVi: 'mặc định ở chế độ riêng tư', noteVi: 'Thuật ngữ mô tả thiết kế bảo vệ dữ liệu người dùng.' },
      { phrase: 'guided access', meaningVi: 'quyền tiếp cận có hướng dẫn', noteVi: 'Cụm nêu cách cho phép sử dụng đi kèm hỗ trợ.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-health', topicSlug: 'health', topicEn: 'Health', topicVi: 'Sức khoẻ',
    title: 'Taxes on unhealthy food',
    promptText: 'Governments should impose higher taxes on food and drinks that are high in sugar, salt or fat. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Diet-related illness places a substantial burden on individuals and health services, prompting proposals for higher taxes on unhealthy products. I support carefully designed taxes on items with little nutritional value, particularly sugary drinks, but taxation should be one part of a broader policy. It should not make affordable food harder to obtain for households with limited incomes.', vi: 'Bệnh liên quan đến chế độ ăn tạo gánh nặng đáng kể cho cá nhân và dịch vụ y tế, dẫn đến đề xuất tăng thuế với sản phẩm không lành mạnh. Tôi ủng hộ thuế được thiết kế cẩn trọng đối với mặt hàng ít giá trị dinh dưỡng, đặc biệt là đồ uống nhiều đường, nhưng thuế chỉ nên là một phần của chính sách rộng hơn. Nó không được khiến thực phẩm giá hợp lý trở nên khó mua hơn với hộ thu nhập thấp.', focusVi: 'Mở bài nêu quan điểm ủng hộ có điều kiện, xác định nhóm sản phẩm và giới hạn công bằng.' },
      { en: 'A price increase can encourage manufacturers to reformulate products and consumers to reduce frequent purchases. The evidence is especially persuasive for sugary beverages, which provide calories without making people feel full. Revenue can fund school meals, clean drinking water and nutrition education, turning a financial measure into a direct public-health benefit. When the policy is predictable, companies have an incentive to lower sugar content rather than simply absorb the tax.', vi: 'Giá tăng có thể khuyến khích nhà sản xuất điều chỉnh công thức và người tiêu dùng giảm mua thường xuyên. Bằng chứng thuyết phục nhất với đồ uống có đường, loại cung cấp năng lượng nhưng không khiến người dùng thấy no. Nguồn thu có thể tài trợ bữa ăn học đường, nước uống sạch và giáo dục dinh dưỡng, biến biện pháp tài chính thành lợi ích sức khoẻ công trực tiếp. Khi chính sách có thể dự đoán, công ty có động lực giảm lượng đường thay vì chỉ chịu khoản thuế.', focusVi: 'Thân bài 1 nêu cơ chế tác động và cách sử dụng nguồn thu.' },
      { en: 'However, a broad tax on all foods high in fat or salt could penalise affordable staples and be difficult to apply fairly. People do not choose diets in a vacuum: price, local availability, work schedules and food marketing shape their options. Governments should define the taxable categories transparently and pair the levy with subsidies for fruit, vegetables and basic nutritious foods. They should also improve school and workplace meals, so healthier choices are convenient rather than merely recommended.', vi: 'Tuy nhiên, thuế rộng với mọi thực phẩm nhiều chất béo hoặc muối có thể phạt các món ăn cơ bản giá rẻ và khó áp dụng công bằng. Mọi người không lựa chọn chế độ ăn trong khoảng chân không: giá cả, nguồn cung địa phương, lịch làm việc và quảng cáo thực phẩm đều định hình lựa chọn. Chính phủ nên xác định rõ nhóm hàng chịu thuế và kết hợp khoản thu với trợ giá trái cây, rau củ cùng thực phẩm dinh dưỡng cơ bản. Đồng thời, cần cải thiện bữa ăn ở trường và nơi làm việc để lựa chọn lành mạnh trở nên tiện lợi chứ không chỉ được khuyến nghị.', focusVi: 'Thân bài 2 nêu hạn chế phân phối và đề xuất biện pháp hỗ trợ đi kèm.' },
      { en: 'A targeted tax can improve health if it changes product design and finances accessible alternatives. Its success should be measured by dietary and health outcomes, not just by the revenue collected. With transparent rules and protections for low-income families, this policy is a reasonable component of prevention rather than a stand-alone solution.', vi: 'Thuế có mục tiêu có thể cải thiện sức khoẻ nếu làm thay đổi thiết kế sản phẩm và tài trợ lựa chọn dễ tiếp cận. Thành công nên được đánh giá qua chế độ ăn và kết quả sức khoẻ, không chỉ qua số thu. Với quy định minh bạch và bảo vệ hộ thu nhập thấp, đây là một thành phần hợp lý của phòng bệnh chứ không phải giải pháp đơn lẻ.', focusVi: 'Kết luận nhắc lại điều kiện đánh giá và vai trò bổ trợ của thuế.' },
    ],
    vocabulary: [
      { phrase: 'reformulate products', meaningVi: 'điều chỉnh công thức sản phẩm', noteVi: 'Động từ chuyên biệt trong bối cảnh nhà sản xuất giảm thành phần không tốt.' },
      { phrase: 'nutritional value', meaningVi: 'giá trị dinh dưỡng', noteVi: 'Cụm khái quát để đánh giá chất lượng thực phẩm.' },
      { phrase: 'affordable staples', meaningVi: 'thực phẩm cơ bản có giá phải chăng', noteVi: 'Cụm quan trọng khi phân tích công bằng trong chính sách thuế.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-society', topicSlug: 'society', topicEn: 'Society', topicVi: 'Xã hội',
    title: 'Car-free city centres',
    promptText: 'Private cars should be banned from the centres of large cities. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Heavy traffic makes city centres noisy, polluted and unpleasant for pedestrians. I agree that private cars should be restricted in the busiest central districts, but a complete ban would be unfair unless reliable alternatives and exemptions are available. The aim should be to reduce unnecessary driving while keeping the centre accessible to people with different needs.', vi: 'Giao thông đông đúc khiến trung tâm thành phố ồn ào, ô nhiễm và không dễ chịu cho người đi bộ. Tôi đồng ý nên hạn chế ô tô cá nhân ở các khu trung tâm đông nhất, nhưng cấm hoàn toàn sẽ bất công nếu thiếu lựa chọn thay thế đáng tin cậy và ngoại lệ cần thiết. Mục tiêu nên là giảm chuyến lái xe không cần thiết mà vẫn giúp mọi người với nhu cầu khác nhau tiếp cận trung tâm.', focusVi: 'Mở bài thể hiện quan điểm đồng ý có điều kiện và nêu tiêu chí công bằng.' },
      { en: 'Fewer cars would give buses more room to move and make walking or cycling safer. Residents and workers would breathe less exhaust, while shops could benefit from wider pavements where people are more likely to stop. Delivery vehicles could enter during scheduled periods, and emergency services would retain access. Several streets could be redesigned as public spaces rather than corridors used mainly for through-traffic, improving the experience of both residents and visitors.', vi: 'Ít ô tô hơn sẽ tạo thêm không gian cho xe buýt di chuyển và giúp đi bộ hoặc đạp xe an toàn hơn. Cư dân và người lao động sẽ hít ít khí thải hơn, còn cửa hàng có thể hưởng lợi từ vỉa hè rộng nơi mọi người dễ dừng chân. Xe giao hàng có thể vào theo khung giờ, còn dịch vụ khẩn cấp vẫn được tiếp cận. Một số tuyến phố có thể được thiết kế lại thành không gian công cộng thay vì hành lang chủ yếu dành cho xe chạy xuyên qua, cải thiện trải nghiệm của cư dân lẫn du khách.', focusVi: 'Thân bài 1 triển khai lợi ích về giao thông, sức khoẻ và hoạt động đường phố.' },
      { en: 'A city-wide prohibition could disadvantage people who live far from transit, have mobility needs or work outside normal hours. Small businesses may also face higher costs if deliveries become complicated. These concerns can be addressed through accessible shuttle services, permits for disabled residents, freight windows and a phased introduction. Before expanding a restriction, authorities should monitor travel times and provide extra buses; a policy that creates hardship without a usable alternative will lose public support.', vi: 'Lệnh cấm trên toàn thành phố có thể gây bất lợi cho người sống xa giao thông công cộng, có nhu cầu di chuyển đặc biệt hoặc làm ngoài giờ thông thường. Doanh nghiệp nhỏ cũng có thể chịu chi phí cao hơn nếu giao hàng trở nên phức tạp. Có thể giải quyết các lo ngại này bằng xe trung chuyển dễ tiếp cận, giấy phép cho cư dân khuyết tật, khung giờ vận tải và triển khai theo từng giai đoạn. Trước khi mở rộng hạn chế, chính quyền nên theo dõi thời gian đi lại và tăng xe buýt; chính sách gây khó khăn mà không có lựa chọn sử dụng được sẽ mất sự ủng hộ.', focusVi: 'Thân bài 2 thừa nhận tác động không đồng đều và đưa cơ chế giảm thiểu.' },
      { en: 'Restricting cars in central districts is a sensible response to pollution and congestion, provided access is redesigned rather than simply removed. Cities should start with the most crowded streets, protect essential users and invest in alternatives before tightening the rules. This gradual approach can make the centre cleaner without shifting the burden onto those with the fewest choices.', vi: 'Hạn chế ô tô ở khu trung tâm là phản ứng hợp lý trước ô nhiễm và ùn tắc, miễn là cách tiếp cận được thiết kế lại chứ không chỉ bị xoá bỏ. Thành phố nên bắt đầu ở những tuyến đông nhất, bảo vệ người cần tiếp cận thiết yếu và đầu tư phương án thay thế trước khi siết quy định. Cách làm dần dần có thể khiến trung tâm sạch hơn mà không đẩy gánh nặng sang những người ít lựa chọn nhất.', focusVi: 'Kết luận khẳng định đồng ý có điều kiện và nguyên tắc triển khai công bằng.' },
    ],
    vocabulary: [
      { phrase: 'through-traffic', meaningVi: 'giao thông chạy xuyên qua khu vực', noteVi: 'Từ ghép chỉ xe đi ngang qua mà không dừng ở địa điểm.' },
      { phrase: 'freight windows', meaningVi: 'khung giờ dành cho xe vận tải', noteVi: 'Cụm ngắn gọn cho lịch giao nhận có kiểm soát.' },
      { phrase: 'phase in a restriction', meaningVi: 'triển khai hạn chế theo giai đoạn', noteVi: 'Động từ cụm giúp đề xuất chính sách thực tế.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-work', topicSlug: 'work', topicEn: 'Work', topicVi: 'Công việc',
    title: 'Changing jobs to gain experience',
    promptText: 'People should change jobs every few years in order to gain a wider range of experience. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Moving between employers can expose workers to new teams, methods and responsibilities. However, I disagree that people should be expected to change jobs on a fixed schedule. A varied career can be valuable, but the right pace depends on the person’s goals, profession and opportunities to develop within an existing role.', vi: 'Chuyển giữa các nhà tuyển dụng có thể giúp người lao động tiếp xúc với nhóm, phương pháp và trách nhiệm mới. Tuy nhiên, tôi không đồng ý rằng mọi người nên bị kỳ vọng đổi việc theo lịch cố định. Sự nghiệp đa dạng có thể có giá trị, nhưng nhịp độ phù hợp tuỳ mục tiêu, ngành nghề và cơ hội phát triển trong vị trí hiện tại.', focusVi: 'Mở bài phản đối quy tắc cứng nhắc và đưa ra lập trường có điều kiện.' },
      { en: 'Changing jobs can prevent a capable employee from becoming trapped in work that no longer teaches them anything. Someone who moves from a small firm to a larger organisation may learn to manage a budget, supervise colleagues or serve a wider customer base. A new workplace can also improve pay when promotion is limited internally. For early-career workers, carefully chosen moves may broaden skills quickly and reveal which kind of work suits them best.', vi: 'Đổi việc có thể giúp một nhân viên giỏi không bị mắc kẹt trong công việc không còn dạy thêm điều gì. Người chuyển từ doanh nghiệp nhỏ sang tổ chức lớn hơn có thể học quản lý ngân sách, hướng dẫn đồng nghiệp hoặc phục vụ nhóm khách hàng rộng hơn. Nơi làm mới cũng có thể cải thiện thu nhập khi cơ hội thăng tiến nội bộ hạn chế. Với người đầu sự nghiệp, những lần chuyển việc được cân nhắc kỹ có thể mở rộng kỹ năng nhanh và giúp họ nhận ra kiểu công việc phù hợp nhất.', focusVi: 'Thân bài 1 công nhận lợi ích của thay đổi có chủ đích.' },
      { en: 'Yet frequent moves can interrupt the deeper learning that comes from seeing a long project through and taking responsibility for its results. Some professions require trust built over years, while others provide structured promotion and specialist training inside one organisation. Switching without a clear reason may also concern employers, particularly if a worker leaves before developing a strong record. Rather than counting years in each job, people should review whether they are learning, contributing fairly and moving towards a realistic career goal.', vi: 'Tuy nhiên, chuyển việc thường xuyên có thể làm gián đoạn quá trình học sâu hơn vốn hình thành khi theo một dự án đến cùng và chịu trách nhiệm về kết quả. Một số nghề đòi hỏi niềm tin được xây dựng qua nhiều năm, còn nghề khác có lộ trình thăng tiến và đào tạo chuyên môn ngay trong một tổ chức. Đổi việc thiếu lý do rõ ràng cũng có thể khiến nhà tuyển dụng lo ngại, đặc biệt nếu nhân viên rời đi trước khi tạo được thành tích tốt. Thay vì đếm số năm ở mỗi nơi, mọi người nên xem mình có đang học hỏi, đóng góp công bằng và tiến tới mục tiêu nghề nghiệp thực tế hay không.', focusVi: 'Thân bài 2 trình bày chi phí của việc đổi việc quá thường xuyên và nêu tiêu chí thay thế.' },
      { en: 'Job mobility is useful when it moves a worker towards meaningful development, not when it becomes an obligation in itself. Employees should compare external opportunities with the chance to grow where they are, and employers should make internal progression more transparent. A career can be broad through varied projects as well as through changing organisations.', vi: 'Tính linh động nghề nghiệp hữu ích khi giúp người lao động phát triển thực chất, chứ không phải khi nó tự trở thành nghĩa vụ. Nhân viên nên so sánh cơ hội bên ngoài với khả năng trưởng thành ở nơi hiện tại, còn nhà tuyển dụng cần minh bạch hơn về lộ trình nội bộ. Sự nghiệp có thể đa dạng nhờ nhiều dự án khác nhau cũng như nhờ chuyển tổ chức.', focusVi: 'Kết luận tái khẳng định quyền lựa chọn và mở rộng định nghĩa trải nghiệm.' },
    ],
    vocabulary: [
      { phrase: 'structured promotion', meaningVi: 'lộ trình thăng tiến có cấu trúc', noteVi: 'Cụm dùng khi mô tả con đường nghề nghiệp nội bộ.' },
      { phrase: 'job mobility', meaningVi: 'tính linh động nghề nghiệp', noteVi: 'Danh từ chỉ khả năng chuyển vai trò hoặc nơi làm việc.' },
      { phrase: 'internal progression', meaningVi: 'sự phát triển/thăng tiến nội bộ', noteVi: 'Cụm đối lập với chuyển sang nhà tuyển dụng khác.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-transport', topicSlug: 'transport', topicEn: 'Transport', topicVi: 'Giao thông',
    title: 'Free public transport',
    promptText: 'Public transport should be free for everyone in order to reduce traffic and pollution. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Making buses and trains free could encourage people to leave their cars at home, but it would also require a reliable way to replace fare income. I support free public transport for children, older people and low-income residents, while favouring affordable rather than universally free fares for everyone. This targeted approach can improve access without diverting money from service quality.', vi: 'Miễn phí xe buýt và tàu có thể khuyến khích mọi người để ô tô ở nhà, nhưng cũng cần cách đáng tin cậy để bù nguồn thu vé. Tôi ủng hộ giao thông công cộng miễn phí cho trẻ em, người cao tuổi và cư dân thu nhập thấp, đồng thời ưu tiên giá vé phải chăng thay vì miễn phí cho tất cả. Cách tiếp cận có mục tiêu này cải thiện khả năng tiếp cận mà không rút tiền khỏi chất lượng dịch vụ.', focusVi: 'Mở bài nêu ý kiến một phần và phân biệt nhóm ưu tiên với toàn dân.' },
      { en: 'Fare-free travel removes a direct cost for people who depend on buses to reach school, medical appointments or work. Families with several children can save a meaningful amount, and older residents may be more willing to attend community activities. If the change leads to more passengers, crowded roads and local emissions could also fall. These benefits are especially relevant in places where fares represent a barrier to basic mobility rather than a minor household expense.', vi: 'Đi lại miễn vé loại bỏ chi phí trực tiếp với người phụ thuộc vào xe buýt để đến trường, khám bệnh hay nơi làm. Gia đình có nhiều con có thể tiết kiệm đáng kể, còn cư dân lớn tuổi có thể sẵn lòng tham gia hoạt động cộng đồng hơn. Nếu thay đổi thu hút thêm hành khách, đường đông và khí thải địa phương cũng có thể giảm. Lợi ích này đặc biệt quan trọng ở nơi giá vé là rào cản đối với khả năng đi lại cơ bản chứ không phải khoản chi nhỏ trong gia đình.', focusVi: 'Thân bài 1 lý giải lợi ích tiếp cận và tác động môi trường tiềm năng.' },
      { en: 'Universal free travel, however, is expensive and may benefit frequent commuters who can already afford a pass as much as those in need. If a city removes fares without adding capacity, buses may become overcrowded and less reliable, pushing some passengers back towards cars. Funding should therefore be tied to service improvements, such as evening routes, step-free access and frequent connections. Means-tested or age-based concessions can protect vulnerable groups, while a modest fare from other users helps sustain the network.', vi: 'Tuy nhiên, đi lại miễn phí cho tất cả rất tốn kém và có thể mang lại lợi ích ngang nhau cho người đi làm thường xuyên vốn đủ khả năng mua vé tháng và người thật sự cần hỗ trợ. Nếu thành phố xoá giá vé mà không tăng năng lực, xe buýt có thể quá tải và kém tin cậy, khiến một số hành khách quay lại dùng ô tô. Vì vậy, nguồn kinh phí cần gắn với cải thiện dịch vụ như tuyến buổi tối, khả năng lên xuống không bậc và kết nối thường xuyên. Ưu đãi theo thu nhập hoặc độ tuổi bảo vệ nhóm dễ tổn thương, còn khoản vé vừa phải từ người khác giúp duy trì mạng lưới.', focusVi: 'Thân bài 2 phân tích chi phí phổ cập và đề xuất hỗ trợ có mục tiêu gắn với chất lượng.' },
      { en: 'The goal should be an accessible and dependable network, not simply a zero price. Targeted free travel and affordable fares can remove barriers for those most affected while preserving funds for better coverage. Once services are frequent and convenient, they offer a stronger reason to switch from cars than fare removal alone.', vi: 'Mục tiêu nên là mạng lưới dễ tiếp cận và đáng tin cậy, không chỉ là giá bằng không. Đi lại miễn phí có mục tiêu và giá vé hợp lý có thể gỡ rào cản cho nhóm chịu ảnh hưởng nhiều nhất, đồng thời giữ kinh phí để mở rộng tuyến. Khi dịch vụ thường xuyên và thuận tiện, chúng tạo lý do mạnh hơn để bỏ ô tô so với việc chỉ xoá tiền vé.', focusVi: 'Kết luận định nghĩa lại ưu tiên chính sách và chốt giải pháp.' },
    ],
    vocabulary: [
      { phrase: 'fare income', meaningVi: 'nguồn thu từ vé', noteVi: 'Cụm dùng khi phân tích tài chính giao thông công cộng.' },
      { phrase: 'step-free access', meaningVi: 'lối tiếp cận không bậc', noteVi: 'Thuật ngữ thiết kế giúp người dùng xe lăn và xe đẩy.' },
      { phrase: 'means-tested concessions', meaningVi: 'ưu đãi xét theo thu nhập', noteVi: 'Cụm chính sách nhắm hỗ trợ đến người đáp ứng tiêu chí.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-media', topicSlug: 'media', topicEn: 'Media', topicVi: 'Truyền thông',
    title: 'Anonymous sources in journalism',
    promptText: 'Journalists should be allowed to protect the identities of people who provide information anonymously. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Anonymous sources can reveal wrongdoing that powerful people would otherwise keep hidden, but anonymity also makes claims harder for readers to assess. I agree that journalists should be allowed to protect a source’s identity when there is a clear public interest and a credible risk of harm. The privilege should involve rigorous checks rather than automatic trust.', vi: 'Nguồn tin ẩn danh có thể phơi bày sai phạm mà người có quyền lực nếu không sẽ che giấu, nhưng giấu danh tính cũng khiến độc giả khó đánh giá lời khai hơn. Tôi đồng ý nhà báo nên được phép bảo vệ người cung cấp tin khi có lợi ích công rõ ràng và nguy cơ bị hại đáng tin cậy. Đặc quyền này cần đi kèm kiểm chứng nghiêm ngặt chứ không phải tin tưởng tự động.', focusVi: 'Mở bài nêu đồng ý có điều kiện và tiêu chuẩn kiểm chứng.' },
      { en: 'An employee may be the only person able to document unsafe conditions or the misuse of public funds. If their name appears in a report, they could lose a job, face threats or be pressured by an employer before investigators act. Protecting identity makes it more likely that evidence reaches the public and can prompt an independent inquiry. This protection is especially important when a source lacks the resources or authority to challenge an institution openly.', vi: 'Một nhân viên có thể là người duy nhất ghi nhận điều kiện không an toàn hoặc việc lạm dụng tiền công. Nếu tên họ xuất hiện trong bài báo, họ có thể mất việc, bị đe doạ hoặc chịu sức ép từ nhà tuyển dụng trước khi điều tra viên hành động. Bảo vệ danh tính giúp bằng chứng có khả năng đến với công chúng và khởi động điều tra độc lập. Sự bảo vệ này đặc biệt quan trọng khi nguồn tin thiếu nguồn lực hoặc quyền hạn để công khai thách thức một tổ chức.', focusVi: 'Thân bài 1 giải thích lợi ích của bảo mật đối với người tố giác và công chúng.' },
      { en: 'The risk is that an unnamed person may have a personal motive or that a reporter publishes an allegation without sufficient corroboration. Readers cannot judge a source’s position if the newsroom conceals every relevant detail. Editors should therefore know the source’s identity, seek documents or independent confirmation, and explain why anonymity was necessary. Serious accusations should not rest on one unverified account, and subjects must be given a fair opportunity to respond before publication.', vi: 'Rủi ro là người không nêu tên có thể có động cơ cá nhân, hoặc phóng viên đăng cáo buộc mà chưa xác minh đủ. Độc giả không thể đánh giá vị trí của nguồn tin nếu toà soạn che giấu mọi chi tiết liên quan. Vì vậy, biên tập viên cần biết danh tính nguồn, tìm tài liệu hoặc xác nhận độc lập, đồng thời giải thích vì sao cần giữ kín. Cáo buộc nghiêm trọng không nên dựa trên một lời kể chưa kiểm chứng, và đối tượng bị nêu tên cần có cơ hội phản hồi công bằng trước khi đăng.', focusVi: 'Thân bài 2 nêu nguy cơ lạm dụng và quy trình bảo đảm độ tin cậy.' },
      { en: 'Protecting a source can be justified when disclosure would expose them to genuine danger and the information serves the public. This protection should be a carefully reasoned editorial decision, supported by evidence and oversight. Such a standard preserves investigative reporting without asking readers to accept anonymous claims uncritically.', vi: 'Bảo vệ nguồn tin là chính đáng khi việc tiết lộ khiến họ đối mặt với nguy hiểm thực sự và thông tin phục vụ công chúng. Đây nên là quyết định biên tập được cân nhắc kỹ, có bằng chứng và giám sát hỗ trợ. Tiêu chuẩn ấy duy trì hoạt động điều tra mà không yêu cầu độc giả chấp nhận vô điều kiện các lời khai ẩn danh.', focusVi: 'Kết luận tái khẳng định đặc quyền có điều kiện và cân bằng tự do báo chí với trách nhiệm.' },
    ],
    vocabulary: [
      { phrase: 'public interest', meaningVi: 'lợi ích công cộng', noteVi: 'Khái niệm phân biệt tin có giá trị xã hội với tò mò cá nhân.' },
      { phrase: 'independent inquiry', meaningVi: 'cuộc điều tra độc lập', noteVi: 'Cụm danh từ nêu cơ chế xác minh ngoài cơ quan bị cáo buộc.' },
      { phrase: 'corroboration', meaningVi: 'sự xác nhận chéo', noteVi: 'Danh từ học thuật chỉ bằng chứng từ nguồn độc lập.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-crime', topicSlug: 'crime', topicEn: 'Crime', topicVi: 'Tội phạm',
    title: 'Community sentences for minor youth offences',
    promptText: 'Young people who commit minor offences should receive community service instead of a prison sentence. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'A minor offence committed by a young person should be treated seriously, but a short prison term can expose them to harmful influences without addressing the behaviour. I largely agree that supervised community service is a better response in such cases. It can hold a young offender accountable while preserving education and the possibility of reintegration.', vi: 'Hành vi phạm tội nhẹ của người trẻ cần được xem xét nghiêm túc, nhưng án tù ngắn có thể khiến họ tiếp xúc với ảnh hưởng xấu mà không giải quyết hành vi. Tôi phần lớn đồng ý rằng lao động công ích có giám sát là phản ứng tốt hơn trong những trường hợp này. Biện pháp đó yêu cầu người phạm tội chịu trách nhiệm, đồng thời duy trì việc học và khả năng tái hoà nhập.', focusVi: 'Mở bài nêu quan điểm đồng ý có giới hạn với trường hợp phạm tội nhẹ.' },
      { en: 'A carefully designed community sentence links an action to its consequences. A teenager who damages a park, for instance, might help restore a public space under adult supervision and meet residents affected by the offence. This experience can teach practical responsibility without separating the young person from school or supportive family members. It is also less costly than imprisonment, allowing authorities to reserve secure facilities for people who pose a serious risk.', vi: 'Án lao động công ích được thiết kế cẩn thận gắn hành động với hậu quả của nó. Chẳng hạn, thiếu niên phá hoại công viên có thể giúp khôi phục không gian công cộng dưới sự giám sát của người lớn và gặp gỡ cư dân chịu ảnh hưởng. Trải nghiệm này có thể dạy trách nhiệm thực tế mà không tách người trẻ khỏi trường học hay gia đình hỗ trợ. Biện pháp cũng ít tốn kém hơn giam giữ, giúp chính quyền dành cơ sở an ninh cho người gây ra nguy cơ nghiêm trọng.', focusVi: 'Thân bài 1 giải thích cơ chế chịu trách nhiệm và lợi ích tái hoà nhập.' },
      { en: 'Community service is not suitable for every offence or every offender. A young person who repeatedly threatens others may need a secure setting, and victims should not be expected to accept an intervention that leaves them unsafe. Courts should consider the seriousness of the harm, previous behaviour and the teenager’s circumstances, then combine service with counselling or education where needed. Clear supervision and completion requirements are essential; without them, a community order may look like a consequence with no force.', vi: 'Lao động công ích không phù hợp với mọi tội danh hay mọi người phạm tội. Người trẻ liên tục đe doạ người khác có thể cần môi trường giam giữ an toàn, và không nên yêu cầu nạn nhân chấp nhận biện pháp khiến họ không an toàn. Toà án cần cân nhắc mức độ tổn hại, hành vi trước đây và hoàn cảnh thiếu niên, rồi kết hợp lao động với tư vấn hoặc học tập khi cần. Giám sát rõ ràng và yêu cầu hoàn thành là thiết yếu; thiếu chúng, lệnh phục vụ cộng đồng có thể giống hình phạt không có hiệu lực.', focusVi: 'Thân bài 2 xác định ngoại lệ, bảo vệ nạn nhân và nhấn mạnh giám sát.' },
      { en: 'For non-violent, lower-level offences, community service is generally more constructive than custody. It communicates that harm has consequences while giving a young person a route back into education and ordinary life. A proportionate sentence, supervised well and adjusted to risk, is more likely to prevent a mistake from becoming a lasting criminal record.', vi: 'Với hành vi mức độ nhẹ và không bạo lực, lao động công ích thường mang tính xây dựng hơn giam giữ. Biện pháp cho thấy hành vi gây hại sẽ có hậu quả, đồng thời mở lối để người trẻ quay lại học tập và đời sống bình thường. Hình phạt tương xứng, được giám sát tốt và điều chỉnh theo rủi ro, có khả năng ngăn sai lầm nhất thời trở thành hồ sơ phạm tội kéo dài.', focusVi: 'Kết luận chốt phạm vi áp dụng và liên kết với mục tiêu giảm tái phạm.' },
    ],
    vocabulary: [
      { phrase: 'supervised community service', meaningVi: 'lao động công ích có giám sát', noteVi: 'Cụm nêu rõ hình thức và điều kiện thực thi.' },
      { phrase: 'secure setting', meaningVi: 'môi trường giam giữ an toàn', noteVi: 'Cách nói trung tính về cơ sở quản lý người có rủi ro cao.' },
      { phrase: 'proportionate sentence', meaningVi: 'hình phạt tương xứng', noteVi: 'Nguyên tắc đánh giá mức độ phù hợp giữa hành vi và hình phạt.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-government', topicSlug: 'government', topicEn: 'Government', topicVi: 'Chính phủ',
    title: 'Universal access to the internet',
    promptText: 'Governments should ensure that every citizen has access to a reliable internet connection at little or no cost. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Internet access has become necessary for education, work and communication with public services. I agree that governments should guarantee a basic, affordable connection for every community. This does not mean the state must provide every household with premium service, but it should prevent geography and income from excluding people from essential digital opportunities.', vi: 'Kết nối internet đã trở nên cần thiết cho giáo dục, công việc và giao tiếp với dịch vụ công. Tôi đồng ý chính phủ nên bảo đảm kết nối cơ bản với chi phí hợp lý cho mọi cộng đồng. Điều này không có nghĩa nhà nước phải cung cấp dịch vụ cao cấp cho từng hộ, nhưng cần ngăn khoảng cách địa lý và thu nhập khiến người dân bị loại khỏi cơ hội số thiết yếu.', focusVi: 'Mở bài khẳng định quyền tiếp cận cơ bản, đồng thời giới hạn phạm vi cung cấp.' },
      { en: 'Students increasingly submit assignments, consult libraries and attend lessons through online systems. A household without a stable connection may have to rely on a phone with limited data, making research and remote learning difficult. The same barrier affects jobseekers who must complete applications online or workers who could take part in training only if they can connect reliably. Extending basic broadband can therefore widen access to services that already exist, particularly in rural areas where private providers may see little commercial return.', vi: 'Học sinh ngày càng nộp bài, tra cứu thư viện và tham gia tiết học qua hệ thống trực tuyến. Hộ không có kết nối ổn định có thể phải dùng điện thoại với dữ liệu hạn chế, khiến việc nghiên cứu và học từ xa khó khăn. Rào cản tương tự ảnh hưởng người tìm việc phải nộp hồ sơ trực tuyến hoặc người lao động chỉ có thể tham gia đào tạo khi kết nối đáng tin cậy. Mở rộng băng thông cơ bản vì vậy có thể mở rộng khả năng sử dụng dịch vụ sẵn có, đặc biệt ở vùng nông thôn nơi nhà cung cấp tư nhân ít thấy lợi nhuận.', focusVi: 'Thân bài 1 đưa ví dụ về giáo dục và việc làm, nêu vai trò đầu tư ở vùng khó.' },
      { en: 'A public guarantee must be designed with cost and privacy in mind. Building infrastructure in sparsely populated regions is expensive, and a state-run network should not become a tool for monitoring citizens. Governments can subsidise providers in underserved areas, publish service standards and require transparent data protection. Public libraries and community hubs can offer free access for residents who do not need a home connection, while those who use more data can choose to pay for a faster plan.', vi: 'Bảo đảm của nhà nước cần tính đến chi phí và quyền riêng tư. Xây hạ tầng ở vùng dân cư thưa tốn kém, còn mạng do nhà nước quản lý không nên trở thành công cụ giám sát công dân. Chính phủ có thể trợ cấp nhà cung cấp ở khu vực thiếu dịch vụ, công bố tiêu chuẩn chất lượng và yêu cầu bảo vệ dữ liệu minh bạch. Thư viện công và điểm sinh hoạt cộng đồng có thể cung cấp truy cập miễn phí cho cư dân không cần mạng tại nhà, còn người dùng nhiều dữ liệu có thể trả tiền cho gói nhanh hơn.', focusVi: 'Thân bài 2 thừa nhận chi phí và quyền riêng tư, đề xuất nhiều mô hình cung cấp.' },
      { en: 'Affordable connectivity should be treated as part of modern public infrastructure, alongside transport and electricity. A basic-access guarantee can help people participate in education and employment without requiring universal free premium service. With privacy safeguards and community access points, government support can reduce exclusion while keeping costs proportionate.', vi: 'Kết nối giá hợp lý nên được xem là một phần của hạ tầng công hiện đại, bên cạnh giao thông và điện. Bảo đảm tiếp cận cơ bản giúp mọi người tham gia giáo dục và việc làm mà không cần cung cấp miễn phí gói cao cấp cho tất cả. Với bảo vệ quyền riêng tư và điểm truy cập cộng đồng, hỗ trợ của chính phủ có thể giảm tình trạng bị loại trừ mà vẫn giữ chi phí tương xứng.', focusVi: 'Kết luận nối internet với hạ tầng thiết yếu và nhắc điều kiện triển khai.' },
    ],
    vocabulary: [
      { phrase: 'basic broadband', meaningVi: 'dịch vụ băng thông rộng cơ bản', noteVi: 'Cụm chỉ mức kết nối đủ dùng cho nhu cầu thiết yếu.' },
      { phrase: 'underserved areas', meaningVi: 'khu vực chưa được phục vụ đầy đủ', noteVi: 'Thuật ngữ thường dùng trong quy hoạch hạ tầng.' },
      { phrase: 'public infrastructure', meaningVi: 'hạ tầng công cộng', noteVi: 'Cụm khái quát cho các hệ thống phục vụ cộng đồng.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-culture', topicSlug: 'culture', topicEn: 'Culture', topicVi: 'Văn hoá',
    title: 'Learning about local culture at school',
    promptText: 'Schools should devote more time to teaching students about the history and culture of their local area. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'School timetables cannot include every subject in depth, so adding local history may appear to compete with mathematics or science. I nevertheless agree that pupils should learn more about the culture and history of the place where they live. Studied critically, local knowledge can make education more relevant and help young people understand how their community has changed.', vi: 'Thời khoá biểu không thể dạy sâu mọi môn, nên thêm lịch sử địa phương có vẻ cạnh tranh với toán hay khoa học. Dù vậy, tôi đồng ý học sinh nên tìm hiểu nhiều hơn về văn hoá và lịch sử nơi mình sống. Khi được học với tư duy phản biện, tri thức địa phương khiến giáo dục gắn thực tế hơn và giúp người trẻ hiểu cộng đồng đã thay đổi ra sao.', focusVi: 'Mở bài thừa nhận giới hạn thời lượng rồi nêu quan điểm đồng ý.' },
      { en: 'Lessons can connect broad ideas to places students already know. A unit on migration might use family stories, old maps and local records to show why neighbourhoods contain different languages and traditions. Visits to a historic market or a river site can also make environmental and economic change tangible. When pupils collect oral histories from older residents, they practise interviewing, evaluating sources and writing clearly, so the subject can reinforce skills taught elsewhere in the curriculum.', vi: 'Bài học có thể nối ý tưởng rộng với những địa điểm học sinh đã biết. Một chủ đề về di cư có thể sử dụng chuyện gia đình, bản đồ cũ và hồ sơ địa phương để cho thấy vì sao khu phố có nhiều ngôn ngữ và phong tục. Tham quan chợ cổ hay bờ sông cũng giúp những thay đổi môi trường và kinh tế trở nên cụ thể. Khi học sinh thu thập ký ức truyền miệng từ cư dân lớn tuổi, các em luyện phỏng vấn, đánh giá nguồn và viết rõ ràng, vì vậy môn học còn củng cố kỹ năng ở nơi khác trong chương trình.', focusVi: 'Thân bài 1 minh hoạ cách học địa phương liên hệ kiến thức và kỹ năng.' },
      { en: 'There is a risk that local history becomes a simplified story designed to make pupils proud rather than informed. Communities often disagree about whose experience is remembered, and some historical buildings represent exploitation as well as achievement. Teachers should use multiple sources and invite students to question whose voices are missing. The topic should supplement national and world history, not replace them, because understanding a locality also requires seeing how it connects to wider forces.', vi: 'Có nguy cơ lịch sử địa phương bị đơn giản hoá thành câu chuyện nhằm khiến học sinh tự hào hơn là hiểu biết. Cộng đồng thường bất đồng về trải nghiệm nào được ghi nhớ, và một số công trình lịch sử vừa thể hiện thành tựu vừa gắn với bóc lột. Giáo viên nên dùng nhiều nguồn và khuyến khích học sinh hỏi xem tiếng nói nào còn thiếu. Chủ đề này nên bổ sung cho lịch sử quốc gia và thế giới, không thay thế chúng, vì hiểu địa phương cũng cần thấy nơi đó liên kết với các lực lượng rộng hơn.', focusVi: 'Thân bài 2 nêu rủi ro thiên lệch và điều kiện giảng dạy cân bằng.' },
      { en: 'Local culture deserves a stronger place in school when it is taught with evidence and more than one perspective. It can help students see their surroundings as part of an ongoing history rather than a fixed tradition. A limited, well-designed programme would deepen belonging without narrowing the education they receive.', vi: 'Văn hoá địa phương xứng đáng có vị trí lớn hơn trong trường học khi được dạy dựa trên bằng chứng và nhiều góc nhìn. Điều này giúp học sinh xem môi trường quanh mình là một phần của lịch sử đang tiếp diễn chứ không phải truyền thống bất biến. Chương trình được thiết kế tốt và có thời lượng hợp lý sẽ tăng cảm giác gắn bó mà không thu hẹp nền giáo dục của các em.', focusVi: 'Kết luận chốt quan điểm và nhấn mạnh yêu cầu đa chiều.' },
    ],
    vocabulary: [
      { phrase: 'oral histories', meaningVi: 'lịch sử truyền miệng', noteVi: 'Lời kể được ghi lại từ người từng trải qua sự kiện hoặc thời kỳ.' },
      { phrase: 'multiple sources', meaningVi: 'nhiều nguồn tư liệu', noteVi: 'Cụm dùng khi đề xuất cách giảm thiên lệch.' },
      { phrase: 'a sense of belonging', meaningVi: 'cảm giác thuộc về/gắn bó', noteVi: 'Cụm thường dùng về cộng đồng và bản sắc.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-tourism', topicSlug: 'tourism', topicEn: 'Tourism', topicVi: 'Du lịch',
    title: 'Limiting international travel for environmental reasons',
    promptText: 'International travel should be restricted because it contributes to environmental damage. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Air travel contributes to greenhouse-gas emissions, and popular destinations can suffer from overcrowding. However, I disagree that international travel should be broadly restricted. Governments should reduce the environmental cost of transport and manage fragile destinations, while recognising that travel also supports livelihoods and cultural exchange.', vi: 'Di chuyển bằng máy bay góp phần tạo khí nhà kính, còn điểm đến nổi tiếng có thể chịu cảnh quá tải. Tuy nhiên, tôi không đồng ý rằng nên hạn chế rộng rãi du lịch quốc tế. Chính phủ cần giảm chi phí môi trường của giao thông và quản lý điểm đến mong manh, đồng thời công nhận du lịch hỗ trợ sinh kế và giao lưu văn hoá.', focusVi: 'Mở bài nêu vấn đề môi trường nhưng bác bỏ biện pháp hạn chế chung.' },
      { en: 'Travel connects relatives who live across borders, allows students to experience unfamiliar societies and sustains jobs in regions with few industries. A small island, for example, may rely on visitors to support ferries, food producers and local guides. Banning or heavily limiting journeys would affect residents whose income depends on these services, as well as travellers with family or educational reasons. A general restriction would also treat a business trip and a high-impact leisure holiday as if their purposes were identical.', vi: 'Du lịch kết nối người thân sống ở các quốc gia khác nhau, cho phép sinh viên trải nghiệm xã hội xa lạ và duy trì việc làm tại vùng ít ngành nghề. Chẳng hạn, một hòn đảo nhỏ có thể dựa vào du khách để hỗ trợ phà, nhà sản xuất thực phẩm và hướng dẫn viên địa phương. Cấm hoặc hạn chế mạnh các chuyến đi sẽ ảnh hưởng đến cư dân sống nhờ dịch vụ này cũng như người đi thăm gia đình hay học tập. Hạn chế chung còn đối xử với chuyến công tác và kỳ nghỉ gây tác động lớn như thể mục đích của chúng giống nhau.', focusVi: 'Thân bài 1 trình bày giá trị xã hội và sinh kế, đồng thời chỉ ra sự thiếu phân biệt của lệnh cấm.' },
      { en: 'Environmental damage should instead be reduced through targeted rules. Governments can improve rail links for shorter journeys, require cleaner aviation fuels as they become available and publish the emissions associated with different routes. Destinations can cap visitor numbers at sensitive sites, charge for conservation and keep housing available for residents rather than allowing every property to become a short-term rental. Travellers can choose longer stays and local businesses, reducing repeated transport while increasing the share of spending that remains in the community.', vi: 'Thay vào đó, cần giảm tác hại môi trường bằng quy định có mục tiêu. Chính phủ có thể cải thiện tuyến đường sắt cho hành trình ngắn, yêu cầu nhiên liệu hàng không sạch hơn khi có thể và công bố phát thải của từng tuyến. Điểm đến có thể giới hạn khách tại khu vực nhạy cảm, thu phí bảo tồn và giữ nhà ở cho cư dân thay vì để mọi căn hộ thành nơi cho thuê ngắn hạn. Du khách có thể ở lâu hơn và chọn doanh nghiệp địa phương, giảm việc di chuyển lặp lại đồng thời tăng phần chi tiêu ở lại cộng đồng.', focusVi: 'Thân bài 2 đề xuất giải pháp theo chính phủ, điểm đến và du khách.' },
      { en: 'Environmental responsibility does not require closing borders to ordinary travellers. It requires pricing and managing travel so that the most damaging practices change and local communities retain a voice. Targeted standards and better transport choices are fairer and more effective than a blanket limit on international movement.', vi: 'Trách nhiệm môi trường không đòi hỏi phải đóng biên giới với du khách thông thường. Cần định giá và quản lý việc đi lại để thay đổi những hoạt động gây hại nhất, đồng thời giữ tiếng nói cho cộng đồng địa phương. Tiêu chuẩn có mục tiêu và lựa chọn giao thông tốt hơn công bằng, hiệu quả hơn giới hạn chung với việc đi lại quốc tế.', focusVi: 'Kết luận khẳng định điều chỉnh tác động thay vì cấm di chuyển rộng rãi.' },
    ],
    vocabulary: [
      { phrase: 'greenhouse-gas emissions', meaningVi: 'khí thải gây hiệu ứng nhà kính', noteVi: 'Thuật ngữ trọng tâm cho tác động khí hậu.' },
      { phrase: 'sensitive sites', meaningVi: 'địa điểm/hệ sinh thái nhạy cảm', noteVi: 'Cụm thường dùng khi nói về giới hạn khách tham quan.' },
      { phrase: 'blanket limit', meaningVi: 'giới hạn áp dụng chung', noteVi: 'Cách gọi một chính sách không phân biệt từng trường hợp.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-science', topicSlug: 'science', topicEn: 'Science', topicVi: 'Khoa học',
    title: 'Public funding for curiosity-driven research',
    promptText: 'Governments should fund scientific research even when it has no clear practical application. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Taxpayers reasonably expect public research budgets to address social needs, but not every valuable discovery begins with an obvious use. I strongly agree that governments should support some curiosity-driven science. A portfolio limited to immediate applications would overlook the foundations from which future medical, environmental and technological advances can emerge.', vi: 'Người đóng thuế có lý do để kỳ vọng ngân sách nghiên cứu công giải quyết nhu cầu xã hội, nhưng không phải phát hiện có giá trị nào cũng bắt đầu bằng ứng dụng rõ ràng. Tôi hoàn toàn đồng ý chính phủ nên hỗ trợ một phần nghiên cứu xuất phát từ tò mò khoa học. Danh mục chỉ giới hạn ở ứng dụng trước mắt sẽ bỏ qua nền tảng tạo ra tiến bộ y học, môi trường và công nghệ trong tương lai.', focusVi: 'Mở bài nêu kỳ vọng trách nhiệm và bảo vệ một phần nghiên cứu cơ bản.' },
      { en: 'Researchers investigating how cells communicate or how materials behave may not know what their findings will eventually enable. Yet fundamental knowledge can later help design a medicine, improve a battery or detect a pollutant. Because this path from discovery to application is uncertain, commercial investors may be unwilling to fund early work whose benefits could take decades and be shared widely. Public grants can support careful research that would otherwise never be attempted.', vi: 'Nhà nghiên cứu tìm hiểu cách tế bào giao tiếp hay vật liệu phản ứng có thể chưa biết phát hiện của họ sau này cho phép điều gì. Tuy nhiên, tri thức nền tảng có thể giúp thiết kế thuốc, cải thiện pin hoặc phát hiện chất ô nhiễm. Vì con đường từ khám phá đến ứng dụng không chắc chắn, nhà đầu tư thương mại có thể không muốn tài trợ nghiên cứu ban đầu mà lợi ích mất hàng thập kỷ mới xuất hiện và được chia sẻ rộng. Trợ cấp công có thể hỗ trợ nghiên cứu cẩn trọng vốn có thể không bao giờ được thực hiện.', focusVi: 'Thân bài 1 giải thích giá trị lâu dài và khoảng trống thị trường của nghiên cứu cơ bản.' },
      { en: 'This does not justify funding every proposal without scrutiny. Public agencies should assess the quality of the question, the researchers’ methods and whether results will be openly reported, rather than demanding a guaranteed product. A balanced programme can reserve most funds for health, energy and other priorities while protecting a smaller share for foundational work. Regular review can stop weak projects, but it should recognise that uncertainty is part of discovery rather than proof that research has failed.', vi: 'Điều này không biện minh cho việc tài trợ mọi đề xuất mà không thẩm định. Cơ quan công nên đánh giá chất lượng câu hỏi, phương pháp nghiên cứu và việc kết quả có được công bố mở hay không, thay vì yêu cầu chắc chắn phải có sản phẩm. Chương trình cân bằng có thể dành phần lớn kinh phí cho y tế, năng lượng và ưu tiên khác, đồng thời bảo vệ phần nhỏ cho nghiên cứu nền tảng. Đánh giá định kỳ có thể dừng dự án yếu, nhưng cần công nhận bất định là một phần của khám phá chứ không phải bằng chứng thất bại.', focusVi: 'Thân bài 2 giới hạn lập trường bằng tiêu chí phân bổ và đánh giá minh bạch.' },
      { en: 'Governments should fund basic science alongside research directed at pressing problems. Such support is not a promise that every experiment will produce a useful invention; it is an investment in knowledge that society may need later. Protecting this work, while reviewing its quality openly, is a rational use of public research funding.', vi: 'Chính phủ nên tài trợ khoa học cơ bản song song với nghiên cứu hướng đến vấn đề cấp bách. Sự hỗ trợ này không hứa hẹn mọi thí nghiệm sẽ tạo ra phát minh hữu ích; đó là đầu tư vào tri thức mà xã hội có thể cần sau này. Bảo vệ công việc ấy, đồng thời công khai đánh giá chất lượng, là cách sử dụng hợp lý ngân sách nghiên cứu công.', focusVi: 'Kết luận khẳng định vai trò bổ sung và điều kiện giải trình.' },
    ],
    vocabulary: [
      { phrase: 'curiosity-driven science', meaningVi: 'khoa học xuất phát từ tò mò nghiên cứu', noteVi: 'Cụm phân biệt nghiên cứu cơ bản với nghiên cứu theo đơn đặt hàng.' },
      { phrase: 'foundational work', meaningVi: 'nghiên cứu nền tảng', noteVi: 'Cách gọi gọn các công trình tạo cơ sở tri thức.' },
      { phrase: 'openly reported', meaningVi: 'được công bố một cách minh bạch/mở', noteVi: 'Dùng khi nói về khả năng tiếp cận kết quả nghiên cứu.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-family', topicSlug: 'family', topicEn: 'Family', topicVi: 'Gia đình',
    title: 'Time with grandparents and family history',
    promptText: 'Children should spend more time with their grandparents so that they can learn about their family history. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Children can learn about their family’s past from photographs and documents, but personal stories give that history a human voice. I agree that regular time with grandparents can benefit young people, provided that relationships are safe and enjoyable for both generations. Such contact can strengthen family ties while helping children understand changes in society over time.', vi: 'Trẻ em có thể tìm hiểu quá khứ gia đình qua ảnh và tài liệu, nhưng chuyện kể cá nhân đem lại tiếng nói con người cho lịch sử ấy. Tôi đồng ý việc thường xuyên ở bên ông bà có thể mang lại lợi ích cho người trẻ, miễn là mối quan hệ an toàn và dễ chịu với cả hai thế hệ. Sự gắn kết này có thể củng cố tình cảm gia đình đồng thời giúp trẻ hiểu xã hội thay đổi theo thời gian.', focusVi: 'Mở bài nêu đồng ý có điều kiện và đặt lợi ích trên hai phương diện.' },
      { en: 'Grandparents can explain how a neighbourhood, a workplace or daily routines differed when they were young. A child who hears how a relative migrated for work or adapted to a new technology may see family decisions within a wider historical context. These conversations also let older people pass on recipes, local expressions and practical knowledge that may not appear in formal lessons. Listening and asking questions can help children develop curiosity and respect across generations.', vi: 'Ông bà có thể giải thích khu phố, nơi làm việc hay sinh hoạt hằng ngày khác ra sao khi họ còn trẻ. Trẻ nghe chuyện người thân di cư vì việc làm hoặc thích nghi với công nghệ mới có thể đặt quyết định gia đình vào bối cảnh lịch sử rộng hơn. Những cuộc trò chuyện này cũng giúp người lớn tuổi truyền lại công thức món ăn, cách nói địa phương và kiến thức thực tế vốn không có trong bài học chính thức. Lắng nghe và đặt câu hỏi giúp trẻ phát triển sự tò mò và tôn trọng giữa các thế hệ.', focusVi: 'Thân bài 1 phát triển giá trị tri thức truyền đời và kỹ năng giao tiếp.' },
      { en: 'However, family contact should not be treated as a duty that overrides people’s circumstances. Some grandparents live far away, have health limitations or do not have a close relationship with their grandchildren. Parents may also face work schedules that make frequent visits difficult. Schools and families can preserve stories through calls, shared photo albums or recorded interviews when face-to-face time is impossible. Children should be invited to connect, not pressured to perform affection or repeat a single version of family history.', vi: 'Tuy nhiên, việc gặp gỡ gia đình không nên bị xem là nghĩa vụ lấn át hoàn cảnh mỗi người. Một số ông bà sống xa, có hạn chế sức khoẻ hoặc không có quan hệ gần gũi với cháu. Cha mẹ cũng có thể có lịch làm việc khiến việc thăm thường xuyên trở nên khó khăn. Trường học và gia đình có thể lưu giữ câu chuyện qua cuộc gọi, album ảnh chung hay phỏng vấn ghi âm khi không thể gặp trực tiếp. Trẻ nên được khuyến khích kết nối chứ không bị ép thể hiện tình cảm hay lặp lại một phiên bản duy nhất của lịch sử gia đình.', focusVi: 'Thân bài 2 nêu trường hợp ngoại lệ và mở rộng cách kết nối linh hoạt.' },
      { en: 'Time with grandparents can give children belonging and a richer sense of the past, but it is most valuable when it is mutual rather than compulsory. Families should create regular opportunities for conversation and use other ways to preserve memories when distance or health makes visits difficult. The aim is meaningful connection, not a fixed number of hours.', vi: 'Thời gian bên ông bà có thể đem lại cho trẻ cảm giác gắn bó và hiểu biết phong phú hơn về quá khứ, nhưng chỉ thực sự có giá trị khi là sự kết nối hai chiều chứ không phải bắt buộc. Gia đình nên tạo cơ hội trò chuyện thường xuyên và dùng cách khác để lưu giữ ký ức khi khoảng cách hay sức khoẻ khiến việc thăm nom khó khăn. Mục tiêu là sự kết nối có ý nghĩa, không phải một số giờ cố định.', focusVi: 'Kết luận nhắc điều kiện tự nguyện và chuyển trọng tâm từ thời lượng sang chất lượng.' },
    ],
    vocabulary: [
      { phrase: 'historical context', meaningVi: 'bối cảnh lịch sử', noteVi: 'Cụm dùng để đặt câu chuyện riêng trong thay đổi xã hội rộng hơn.' },
      { phrase: 'pass on practical knowledge', meaningVi: 'truyền lại kiến thức thực tế', noteVi: 'Kết hợp tự nhiên khi nói về kinh nghiệm liên thế hệ.' },
      { phrase: 'mutual rather than compulsory', meaningVi: 'mang tính hai chiều thay vì bắt buộc', noteVi: 'Cặp đối lập giúp nêu điều kiện một cách súc tích.' },
    ],
  },
  {
    id: 'sample-t2-extra-opinion-economy', topicSlug: 'economy', topicEn: 'Economy', topicVi: 'Kinh tế',
    title: 'Saving versus spending on leisure',
    promptText: 'People should save as much of their income as possible rather than spend money on leisure activities. To what extent do you agree or disagree?',
    paragraphs: [
      { en: 'Saving protects people against emergencies and helps them plan for future needs, but treating every leisure purchase as wasteful is too narrow a view of financial responsibility. I disagree that people should save as much as possible at the expense of all recreation. A sensible budget should balance security with a quality of life that people can enjoy in the present.', vi: 'Tiết kiệm bảo vệ mọi người trước tình huống khẩn cấp và giúp lên kế hoạch cho nhu cầu tương lai, nhưng xem mọi khoản chi giải trí là lãng phí là cách nhìn quá hạn hẹp về trách nhiệm tài chính. Tôi không đồng ý rằng mọi người nên tiết kiệm tối đa bằng cách hy sinh mọi hoạt động thư giãn. Ngân sách hợp lý cần cân bằng sự an toàn với chất lượng cuộc sống có thể tận hưởng ở hiện tại.', focusVi: 'Mở bài phản đối cực đoan và xác lập nguyên tắc cân bằng.' },
      { en: 'A reserve of money can prevent a temporary setback from becoming a crisis. Someone who has savings may repair a broken appliance or cover a period without work without relying on expensive credit. Long-term goals such as education, housing or retirement also require people to delay some spending today. These reasons make regular saving important, particularly for households whose income is irregular or whose essential costs could rise unexpectedly.', vi: 'Khoản dự phòng có thể ngăn khó khăn tạm thời biến thành khủng hoảng. Người có tiền tiết kiệm có thể sửa thiết bị hỏng hoặc trang trải giai đoạn thất nghiệp mà không phải dựa vào tín dụng đắt đỏ. Mục tiêu dài hạn như học tập, nhà ở hay nghỉ hưu cũng đòi hỏi mọi người trì hoãn một phần chi tiêu hiện tại. Những lý do này khiến tiết kiệm đều đặn trở nên quan trọng, đặc biệt với hộ có thu nhập thất thường hoặc chi phí thiết yếu có thể tăng bất ngờ.', focusVi: 'Thân bài 1 công nhận vai trò an toàn và mục tiêu dài hạn của tiết kiệm.' },
      { en: 'However, leisure can support health, relationships and motivation rather than merely provide luxury. A modest weekend trip, a sports club or a meal with friends may help people manage stress and maintain social ties. Spending also supports workers and businesses that provide cultural or recreational services. This does not justify borrowing for expensive entertainment; it means that, after essential bills and a realistic saving target, planned enjoyment can be part of a responsible budget. The right balance depends on income and obligations.', vi: 'Tuy nhiên, hoạt động giải trí có thể hỗ trợ sức khoẻ, các mối quan hệ và động lực chứ không chỉ là xa xỉ. Chuyến đi cuối tuần khiêm tốn, câu lạc bộ thể thao hay bữa ăn với bạn bè có thể giúp giảm căng thẳng và duy trì kết nối xã hội. Chi tiêu cũng hỗ trợ người lao động và doanh nghiệp cung cấp dịch vụ văn hoá, giải trí. Điều này không biện minh cho việc vay tiền để giải trí đắt đỏ; nó có nghĩa là sau khi trả chi phí thiết yếu và đạt mục tiêu tiết kiệm thực tế, niềm vui có kế hoạch có thể nằm trong ngân sách có trách nhiệm. Sự cân bằng phù hợp tuỳ thu nhập và nghĩa vụ.', focusVi: 'Thân bài 2 giải thích giá trị của giải trí và đặt điều kiện ngân sách.' },
      { en: 'Financial security and enjoyment are not mutually exclusive if people plan their spending honestly. Saving should protect future choices, not eliminate every source of satisfaction in the present. A realistic budget sets aside money for emergencies and long-term goals while allowing affordable leisure that supports wellbeing.', vi: 'An toàn tài chính và niềm vui không loại trừ nhau nếu mọi người lập kế hoạch chi tiêu trung thực. Tiết kiệm nên bảo vệ lựa chọn tương lai, không xoá bỏ mọi nguồn vui trong hiện tại. Ngân sách thực tế dành tiền cho tình huống khẩn cấp và mục tiêu lâu dài, đồng thời cho phép hoạt động giải trí vừa túi tiền hỗ trợ sức khoẻ tinh thần.', focusVi: 'Kết luận tóm lược nguyên tắc cân bằng giữa tương lai và hiện tại.' },
    ],
    vocabulary: [
      { phrase: 'expensive credit', meaningVi: 'tín dụng có chi phí cao', noteVi: 'Cụm dùng khi nói về vay nợ lãi suất cao.' },
      { phrase: 'mutually exclusive', meaningVi: 'loại trừ lẫn nhau', noteVi: 'Cụm trang trọng để bác bỏ lựa chọn nhị nguyên.' },
      { phrase: 'a realistic saving target', meaningVi: 'mục tiêu tiết kiệm thực tế', noteVi: 'Cụm giúp lập luận tránh khuyến nghị cực đoan.' },
    ],
  },
];

export const WRITING_SAMPLES_EXTRA_OPINION: WritingSample[] = SEEDS.map(makeOpinion);
